import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.1lR7qgqY.js";const u=JSON.parse('{"title":"手冊簡介","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":null}'),c={name:"guide/index.md"};function i(r,e,l,s,n,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="手冊簡介" tabindex="-1">手冊簡介 <a class="header-anchor" href="#手冊簡介" aria-label="Permalink to &quot;手冊簡介&quot;">​</a></h1><p>這份手冊是文件網站的 POC, 用來確認版型、撰寫方式與發布流程是否符合需求. 確認後, 把範例內容換成正式內容即可.</p><h2 id="網站的組成" tabindex="-1">網站的組成 <a class="header-anchor" href="#網站的組成" aria-label="Permalink to &quot;網站的組成&quot;">​</a></h2><p>畫面分成三個區塊:</p><table tabindex="0"><thead><tr><th>區塊</th><th>位置</th><th>內容來源</th></tr></thead><tbody><tr><td>左側選單</td><td>畫面左邊</td><td><code>content/.vitepress/config.mts</code> 的 <code>sidebar</code> 設定</td></tr><tr><td>內文</td><td>畫面中間</td><td>每一頁的 Markdown 檔案</td></tr><tr><td>本頁目錄</td><td>畫面右邊</td><td>自動擷取頁面裡的 <code>##</code> 與 <code>###</code> 標題</td></tr></tbody></table><p>手機上, 左側選單會收進左上角的「選單」按鈕, 本頁目錄則收進頁首的下拉選單.</p><h2 id="發布流程-核准後才上線" tabindex="-1">發布流程: 核准後才上線 <a class="header-anchor" href="#發布流程-核准後才上線" aria-label="Permalink to &quot;發布流程: 核准後才上線&quot;">​</a></h2><p>所有修改都必須經過 Pull Request (PR) 審核, 核准者按下 Merge 之後, 網站才會更新.</p><ol><li>在新分支修改 <code>content/</code> 裡的 Markdown 檔案.</li><li>執行 <code>npm run docs:build</code>, 產生網站檔案到 <code>docs/</code> 資料夾.</li><li>把修改與 <code>docs/</code> 一起 commit, push 後開 PR.</li><li>核准者在 GitHub 上檢視 PR, 確認無誤後按 Merge.</li><li>GitHub Pages 從 <code>main</code> 分支的 <code>docs/</code> 資料夾發布, 約一至兩分鐘後網站更新.</li></ol><div class="tip custom-block"><p class="custom-block-title">為什麼合併就等於發布</p><p>GitHub Pages 只讀 <code>main</code> 分支. 修改留在其他分支或尚未合併的 PR 時, 網站內容不會改變, 所以 Merge 就是唯一的發布開關.</p></div><div class="tip custom-block"><p class="custom-block-title">不需付費</p><p>這個流程不使用 GitHub Actions, 只用 GitHub Pages 內建的分支發布, 公開 repo 不需付費.</p></div><h2 id="審核-pr-時看哪裡" tabindex="-1">審核 PR 時看哪裡 <a class="header-anchor" href="#審核-pr-時看哪裡" aria-label="Permalink to &quot;審核 PR 時看哪裡&quot;">​</a></h2><p>PR 的「Files changed」會同時列出 <code>content/</code> 和 <code>docs/</code> 的變更. 審核時看 <code>content/</code> 底下的 Markdown 即可; <code>docs/</code> 是自動產生的網站檔案, 不需要逐行檢查.</p><h2 id="適合放什麼內容" tabindex="-1">適合放什麼內容 <a class="header-anchor" href="#適合放什麼內容" aria-label="Permalink to &quot;適合放什麼內容&quot;">​</a></h2><p>GitHub Pages 的網站是公開的, 任何拿到網址的人都看得到. 因此適合放工具使用說明、公開的技術筆記與教學內容; 含客戶資訊或內部資料的內容, 請改放需要登入的平台.</p>',15)])])}const b=t(c,[["render",i]]);export{u as __pageData,b as default};
